"""Hidden behavioral tests for cmark: breaks. Generated by pbkit from the gold binary."""


def test_kitchen_sink_html_hardbreaks(run):
    r = run(args=['--hardbreaks'], stdin=b'# Heading *one*\n\nSetext heading\n--------------\n\nA paragraph with *emph*, **strong**, ***both***, `code`, a [link](http://example.com "Title"),\nan ![image](img.png "Img"), <http://auto.link>, <me@example.com>, a hard\\\nbreak and a soft\nbreak. Entities: &copy; &#x27; &#39; &nbsp;. Backslash \\* escapes.\n\n> A block quote\n> with *two* lines\n>\n> > nested quote\n\n1. first\n2. second\n   - nested bullet\n   - another\n\n     with a paragraph\n3. third\n\n- [ ] not a task list\n* different bullet\n\n```python\ndef f(x):\n    return x * 2\n```\n\n    indented code block\n\n<div class="raw">\n*not emph*\n</div>\n\nInline <span>html</span> and <!-- comment -->.\n\n***\n\n[ref link][ref] and [collapsed][] and [shortcut].\n\n[ref]: /url "ref title"\n[collapsed]: </with spaces>\n[shortcut]: http://x.y \'single\'\n')
    assert r.stdout == b'<h1>Heading <em>one</em></h1>\n<h2>Setext heading</h2>\n<p>A paragraph with <em>emph</em>, <strong>strong</strong>, <em><strong>both</strong></em>, <code>code</code>, a <a href="http://example.com" title="Title">link</a>,<br />\nan <img src="img.png" alt="image" title="Img" />, <a href="http://auto.link">http://auto.link</a>, <a href="mailto:me@example.com">me@example.com</a>, a hard<br />\nbreak and a soft<br />\nbreak. Entities: \xc2\xa9 \' \' \xc2\xa0. Backslash * escapes.</p>\n<blockquote>\n<p>A block quote<br />\nwith <em>two</em> lines</p>\n<blockquote>\n<p>nested quote</p>\n</blockquote>\n</blockquote>\n<ol>\n<li>first</li>\n<li>second\n<ul>\n<li>\n<p>nested bullet</p>\n</li>\n<li>\n<p>another</p>\n<p>with a paragraph</p>\n</li>\n</ul>\n</li>\n<li>third</li>\n</ol>\n<ul>\n<li>[ ] not a task list</li>\n</ul>\n<ul>\n<li>different bullet</li>\n</ul>\n<pre><code class="language-python">def f(x):\n    return x * 2\n</code></pre>\n<pre><code>indented code block\n</code></pre>\n<!-- raw HTML omitted -->\n<p>Inline <!-- raw HTML omitted -->html<!-- raw HTML omitted --> and <!-- raw HTML omitted -->.</p>\n<hr />\n<p><a href="/url" title="ref title">ref link</a> and <a href="/with%20spaces">collapsed</a> and <a href="http://x.y" title="single">shortcut</a>.</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


