    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <paragraph>\n    <link destination="b c">\n      <text xml:space="preserve">a</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <link destination="e(f)g">\n      <text xml:space="preserve">d</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <link destination="i)j">\n      <text xml:space="preserve">h</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <link destination="l" title="m">\n      <text xml:space="preserve">k</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <link destination="javascript:alert(1)">\n      <text xml:space="preserve">n</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <link destination="data:image/png;base64,x">\n      <text xml:space="preserve">o</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <link destination="vbscript:x">\n      <text xml:space="preserve">p</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <link destination="file:///etc">\n      <text xml:space="preserve">q</text>\n    </link>\n    <text xml:space="preserve"> </text>\n    <image destination="data:text/html;x">\n      <text xml:space="preserve">r</text>\n    </image>\n    <text xml:space="preserve"> </text>\n    <link destination="javascript:y">\n      <text xml:space="preserve">javascript:y</text>\n    </link>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


