def test_nested_structure_commonmark_nobreaks(run):
    r = run(args=['-t', 'commonmark', '--nobreaks'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'> 1.  >   - a b\n> \n> 2.  c\n>     \n>     ``` \n>     code in list\n>     ```\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_latex_hardbreaks(run):
    r = run(args=['-t', 'latex', '--hardbreaks'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'\\begin{quote}\n\\begin{enumerate}\n\\item \\begin{quote}\n\\begin{itemize}\n\\item a\\\\\nb\n\n\\end{itemize}\n\n\\end{quote}\n\n\\item c\n\n\\begin{verbatim}\ncode in list\n\\end{verbatim}\n\n\\end{enumerate}\n\n\\end{quote}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nested_structure_latex_nobreaks(run):
    r = run(args=['-t', 'latex', '--nobreaks'], stdin=b'> 1. > - a\n>    >   b\n> 2. c\n>\n>        code in list\n')
    assert r.stdout == b'\\begin{quote}\n\\begin{enumerate}\n\\item \\begin{quote}\n\\begin{itemize}\n\\item a b\n\n\\end{itemize}\n\n\\end{quote}\n\n\\item c\n\n\\begin{verbatim}\ncode in list\n\\end{verbatim}\n\n\\end{enumerate}\n\n\\end{quote}\n'
    assert r.stderr == b''
    assert r.returncode == 0
